describe('API Error Banner Display', () => {
  const apiEndpoint = '/api/data';
  const errorBannerSelector = '[data-testid="error-banner"]';
  const errorMessageSelector = '[data-testid="error-message"]';
  const retryButtonSelector = '[data-testid="retry-button"]';

  beforeEach(() => {
    cy.visit('/');
  });

  it('should display error banner when API call fails with 500 status', () => {
    cy.intercept('GET', apiEndpoint, {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('failedApiCall');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@failedApiCall');

    cy.get(errorBannerSelector).should('be.visible');
    cy.get(errorMessageSelector).should('contain', 'Internal Server Error');
    cy.get(errorBannerSelector).should('have.class', 'error');
  });

  it('should display error banner with appropriate message for 404 error', () => {
    cy.intercept('GET', apiEndpoint, {
      statusCode: 404,
      body: { error: 'Resource not found' }
    }).as('notFoundError');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@notFoundError');

    cy.get(errorBannerSelector).should('be.visible');
    cy.get(errorMessageSelector).should('contain', 'Resource not found');
  });

  it('should allow user to retry after API failure', () => {
    cy.intercept('GET', apiEndpoint, {
      statusCode: 500,
      body: { error: 'Server Error' }
    }).as('firstFailedCall');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@firstFailedCall');

    cy.get(errorBannerSelector).should('be.visible');

    cy.intercept('GET', apiEndpoint, {
      statusCode: 200,
      body: { data: 'Success' }
    }).as('successfulRetry');

    cy.get(retryButtonSelector).click();
    cy.wait('@successfulRetry');

    cy.get(errorBannerSelector).should('not.exist');
    cy.get('[data-testid="data-content"]').should('contain', 'Success');
  });

  it('should display error banner for network timeout', () => {
    cy.intercept('GET', apiEndpoint, (req) => {
      req.destroy();
    }).as('networkError');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@networkError');

    cy.get(errorBannerSelector).should('be.visible');
    cy.get(errorMessageSelector).should('contain', 'Network error');
  });

  it('should close error banner when close button is clicked', () => {
    cy.intercept('GET', apiEndpoint, {
      statusCode: 500,
      body: { error: 'Server Error' }
    }).as('failedCall');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@failedCall');

    cy.get(errorBannerSelector).should('be.visible');
    cy.get('[data-testid="error-banner-close"]').click();

    cy.get(errorBannerSelector).should('not.be.visible');
  });

  it('should display error banner for 403 Forbidden with custom message', () => {
    cy.intercept('GET', apiEndpoint, {
      statusCode: 403,
      body: { error: 'Access denied. You do not have permission to access this resource.' }
    }).as('forbiddenError');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@forbiddenError');

    cy.get(errorBannerSelector).should('be.visible');
    cy.get(errorMessageSelector).should('contain', 'Access denied');
    cy.get(errorBannerSelector).should('have.attr', 'role', 'alert');
  });

  it('should handle multiple consecutive API failures gracefully', () => {
    cy.intercept('GET', apiEndpoint, {
      statusCode: 500,
      body: { error: 'Server Error' }
    }).as('failedCall');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@failedCall');
    cy.get(errorBannerSelector).should('be.visible');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@failedCall');
    cy.get(errorBannerSelector).should('be.visible');
    cy.get(errorMessageSelector).should('contain', 'Server Error');
  });
});
